    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data.keys()):
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload and process it.

    Args:
        data: The request payload. Unless ``legacy_mode`` is enabled, this must
            be a dictionary whose keys are all strings.
        legacy_mode: Bypass payload validation for older clients when true.

    Raises:
        TypeError: If validation is enabled and ``data`` is not a dictionary,
            or if any of its keys are not strings.
    """
    if not legacy_mode:
        _validate_payload(data)

    return process(data)

